<script setup lang="ts">
import{onMounted,ref}from'vue';import{storeToRefs}from'pinia';import FinanceSubnav from'../components/FinanceSubnav.vue';import FinanceScenarioBar from'../components/FinanceScenarioBar.vue';import{useFinanceStore}from'../runtime/finance-store';import'./finance-views.css'
const store=useFinanceStore();const{periods,loading,error,scenario,actor}=storeToRefs(store);const year=ref(2026),reasonMonth=ref(''),reason=ref(''),actionError=ref('');async function load(){await store.loadPeriods(year.value)}async function close(month:string){actionError.value='';if(!confirm(`确认结转 ${month}？结转后该月禁止新增资金流水。`))return;try{await store.closePeriod(month)}catch(e){actionError.value=e instanceof Error?e.message:'结转失败'}}async function reverse(){actionError.value='';try{await store.reversePeriod(reasonMonth.value,reason.value);reasonMonth.value='';reason.value=''}catch(e){actionError.value=e instanceof Error?e.message:'反结转失败'}}onMounted(load)
</script>
<template><section class="finance-page"><header class="finance-header"><div><h1>资金结转</h1><p>从账套启用月连续结转；每次原子冻结全部账户期末。</p></div><FinanceScenarioBar :scenario="scenario" :role="actor.role" @scenario="async v=>{await store.setScenario(v);await load()}" @role="async v=>{await store.setRole(v);await load()}"/></header><FinanceSubnav/><div class="finance-toolbar"><label>会计年度<input v-model.number="year" type="number" min="2026" max="2026" @change="load"></label><button class="fin-button" @click="load">刷新</button></div><p v-if="actionError||error" class="finance-warning">{{actionError||error}}</p><div v-if="loading" class="finance-state">正在加载结转期间…</div><div v-else class="finance-cards"><article v-for="card in periods" :key="card.month" class="finance-card"><header><strong>{{card.month}}</strong><span class="fin-status" :class="card.status">{{card.status==='closed'?'已结转':card.status==='open'?'未结转':'不可用'}}</span></header><p v-if="card.period?.status==='closed'">{{card.period.closedBy.name}} · {{card.period.closedAt.slice(0,16).replace('T',' ')}}</p><p v-else-if="card.period?.status==='reversed'">已反结转：{{card.period.reversalReason}}</p><p v-else>按连续月份顺序执行，空月也可结转。</p><button v-if="card.status==='open'" class="fin-button primary" @click="close(card.month)">结转</button><button v-if="card.status==='closed'" class="fin-button danger" @click="reasonMonth=card.month">反结转</button></article></div><div v-if="reasonMonth" class="finance-dialog"><form class="finance-panel finance-form" @submit.prevent="reverse"><div class="wide"><h2>反结转 {{reasonMonth}}</h2><p>只允许最新已结转月且不能存在后续资金流水。</p></div><label class="wide">原因（1～200 字）<textarea v-model.trim="reason" maxlength="200" required></textarea></label><div class="finance-actions"><button type="button" class="fin-button" @click="reasonMonth=''">取消</button><button class="fin-button danger" :disabled="store.saving">确认反结转</button></div></form></div></section></template>
